CREATE TABLE users(id INTEGER PRIMARY KEY CHECK(id>0), username TEXT NOT NULL UNIQUE COLLATE BINARY, password_hash TEXT NOT NULL, display_name TEXT, avatar_id INTEGER REFERENCES uploads(id), status_text TEXT, desired_presence TEXT NOT NULL CHECK(desired_presence IN ('online','idle','dnd','invisible')), created_at INTEGER NOT NULL);
CREATE TABLE sessions(token_hash BLOB PRIMARY KEY CHECK(length(token_hash)=32), user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, last_used_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id,expires_at);
CREATE TABLE relationships(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,other_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('friend','incoming_request','outgoing_request','blocked')),since INTEGER NOT NULL,PRIMARY KEY(user_id,other_id),CHECK(user_id<>other_id));
CREATE INDEX relationship_other ON relationships(other_id,kind);
CREATE TABLE guilds(id INTEGER PRIMARY KEY CHECK(id>0),owner_id INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,icon_id INTEGER REFERENCES uploads(id),created_at INTEGER NOT NULL);
CREATE TABLE guild_members(guild_id INTEGER NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('owner','admin','member')),joined_at INTEGER NOT NULL,PRIMARY KEY(guild_id,user_id));
CREATE INDEX member_user ON guild_members(user_id,guild_id);
CREATE TABLE guild_bans(guild_id INTEGER NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),actor_id INTEGER NOT NULL REFERENCES users(id),reason TEXT,created_at INTEGER NOT NULL,PRIMARY KEY(guild_id,user_id));
CREATE TABLE invites(id INTEGER PRIMARY KEY CHECK(id>0),code_hash BLOB NOT NULL UNIQUE CHECK(length(code_hash)=32),code TEXT NOT NULL,guild_id INTEGER NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,creator_id INTEGER NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL,max_uses INTEGER NOT NULL CHECK(max_uses BETWEEN 1 AND 1000),uses INTEGER NOT NULL CHECK(uses>=0 AND uses<=max_uses));
CREATE TABLE channels(id INTEGER PRIMARY KEY CHECK(id>0),kind TEXT NOT NULL CHECK(kind IN ('category','text','direct','group_dm')),guild_id INTEGER REFERENCES guilds(id) ON DELETE CASCADE,parent_id INTEGER REFERENCES channels(id) ON DELETE SET NULL,name TEXT,topic TEXT,position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 65535),owner_id INTEGER REFERENCES users(id),created_at INTEGER NOT NULL,CHECK((kind IN ('category','text') AND guild_id IS NOT NULL AND name IS NOT NULL AND owner_id IS NULL) OR (kind IN ('direct','group_dm') AND guild_id IS NULL AND parent_id IS NULL AND topic IS NULL)),CHECK(kind<>'category' OR (parent_id IS NULL AND topic IS NULL)));
CREATE INDEX channel_guild ON channels(guild_id,parent_id,position,id);
CREATE TABLE dm_pairs(low_user_id INTEGER NOT NULL REFERENCES users(id),high_user_id INTEGER NOT NULL REFERENCES users(id),channel_id INTEGER NOT NULL UNIQUE REFERENCES channels(id) ON DELETE CASCADE,PRIMARY KEY(low_user_id,high_user_id),CHECK(low_user_id<high_user_id));
CREATE TABLE dm_members(channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,joined_at INTEGER NOT NULL,visible INTEGER NOT NULL CHECK(visible IN(0,1)),PRIMARY KEY(channel_id,user_id));
CREATE INDEX dm_user ON dm_members(user_id,visible,channel_id);
CREATE TABLE messages(id INTEGER PRIMARY KEY CHECK(id>0),channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,author_id INTEGER NOT NULL REFERENCES users(id),content TEXT NOT NULL,created_at INTEGER NOT NULL,edited_at INTEGER,reply_to INTEGER REFERENCES messages(id) ON DELETE SET NULL,deleted_at INTEGER);
CREATE INDEX message_channel ON messages(channel_id,id);
CREATE TABLE message_mentions(message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(message_id,user_id));
CREATE INDEX mention_user ON message_mentions(user_id,message_id);
CREATE TABLE uploads(id INTEGER PRIMARY KEY CHECK(id>0),owner_id INTEGER NOT NULL REFERENCES users(id),purpose TEXT NOT NULL CHECK(purpose IN ('message','avatar','guild_icon')),channel_id INTEGER REFERENCES channels(id) ON DELETE CASCADE,filename TEXT NOT NULL,content_type TEXT NOT NULL,byte_size INTEGER NOT NULL CHECK(byte_size>=0),storage_key TEXT NOT NULL UNIQUE,width INTEGER,height INTEGER,thumbnail_key TEXT,thumbnail_width INTEGER,thumbnail_height INTEGER,thumbnail_size INTEGER,thumbnail_type TEXT,created_at INTEGER NOT NULL,expires_at INTEGER);
CREATE INDEX upload_expiry ON uploads(expires_at);
CREATE INDEX upload_owner ON uploads(owner_id,created_at);
CREATE TABLE message_attachments(message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,attachment_id INTEGER NOT NULL UNIQUE REFERENCES uploads(id),position INTEGER NOT NULL,PRIMARY KEY(message_id,attachment_id));
CREATE TABLE reactions(message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),emoji TEXT NOT NULL,PRIMARY KEY(message_id,user_id,emoji));
CREATE INDEX reaction_message ON reactions(message_id,emoji);
CREATE TABLE read_states(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,last_read_id INTEGER,unread_count INTEGER NOT NULL DEFAULT 0 CHECK(unread_count>=0),mention_count INTEGER NOT NULL DEFAULT 0 CHECK(mention_count>=0),PRIMARY KEY(user_id,channel_id));
CREATE TABLE command_receipts(session_hash BLOB NOT NULL REFERENCES sessions(token_hash) ON DELETE CASCADE,nonce INTEGER NOT NULL CHECK(nonce>0),request_hash BLOB NOT NULL CHECK(length(request_hash)=32),result_msgpack BLOB NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(session_hash,nonce));
CREATE INDEX receipt_expiry ON command_receipts(expires_at);
CREATE TABLE upload_daily_usage(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,utc_day INTEGER NOT NULL,charged_bytes INTEGER NOT NULL CHECK(charged_bytes>=0),PRIMARY KEY(user_id,utc_day));
